import React,{useEffect,useMemo,useRef,useState}from'react';import{createRoot}from'react-dom/client';import{Search,Bell,UserRound,Grid2X2,Eye,Pencil,Printer,CreditCard,Check,X,LockKeyhole,ChevronDown,Palette,SlidersHorizontal,UserCog,Languages,RefreshCw,LogOut,LayoutGrid,List,PlusCircle,MapPinned,Ban,MapPin,Clock3,HandCoins,DoorClosed}from'lucide-react';import'./style.css';import Inventory from'./Inventory';import KitchenKDS from'./KitchenKDS';import{supabase,configured,verifyManagementPassword}from'./lib/supabase';import{bootstrap,saveOrder,payOrder,assignRider,updateOrderStatus,openShift,cashHandover,shiftSummary,closeShift,subscribe,createCustomer,updateExistingOrder}from'./lib/api';
