function Drop({label,icon:Icon,children,className=''}){const[o,setO]=useState(false),r=useRef();useEffect(()=>{const f=e=>r.current&&!r.current.contains(e.target)&&setO(false);addEventListener('mousedown',f);return()=>removeEventListener('mousedown',f)},[]);return <div className={'topDrop '+className} ref={r}><button className="topDropTrigger" onClick={()=>setO(!o)}>{Icon&&<Icon/>}{label}<ChevronDown/></button>{o&&<div className="topDropMenu" onClick={()=>setO(false)}>{children}</div>}</div>}
