function ShiftModal({kind,data,refresh,close}){const[a,setA]=useState('0'),[n,setN]=useState(''),[sum,setSum]=useState(null),[busy,setBusy]=useState(false),[err,setErr]=useState('');useEffect(()=>{kind==='close'&&data.shift&&shiftSummary(data.shift.id).then(setSum).catch(e=>setErr(e.message))},[kind]);const go=async()=>{try{setBusy(true);setErr('');if(kind==='open')await openShift(data.branch.id);if(kind==='handover')await cashHandover(data.shift?.id,data.branch.id,a,n);if(kind==='close')await closeShift(data.shift?.id,a,n);await refresh();close()}catch(e){setErr(e.message)}finally{setBusy(false)}};return <Modal title={kind==='open'?'Day Shift':kind==='handover'?'Cash Handover':'Shift Close'} close={close}><div className="modalBody">{err&&<div className="errorBox">{err}</div>}{kind==='open'?<p>Open the day shift for <b>{data.branch?.name}</b>. Orders cannot be placed until a shift is open.</p>:<>{sum&&<div className="shiftSummary"><span>Sales <b>Rs {money(sum.sales)}</b></span><span>Cash <b>Rs {money(sum.cash)}</b></span><span>Card <b>Rs {money(sum.card)}</b></span><span>Handed over <b>Rs {money(sum.handovers)}</b></span></div>}<label>{kind==='close'?'Closing cash':'Amount'}<input type="number" value={a} onChange={e=>setA(e.target.value)}/></label><label>Notes<textarea value={n} onChange={e=>setN(e.target.value)}/></label></>}<button className="primary" disabled={busy} onClick={go}>{busy?'Working…':kind==='open'?'Open Day Shift':kind==='handover'?'Save Cash Handover':'Close Shift'}</button></div></Modal>}
