function StandardPOS({data,refresh}){const[cart,setCart]=useState([]),[category,setCategory]=useState('all'),[q,setQ]=useState('');const categories=data.categories||[];const products=(data.products||[]).filter(p=>(category==='all'||p.category_id===category)&&(!q||String(p.name||'').toLowerCase().includes(q.toLowerCase())));const add=(p,v)=>{const id=v?.id||p.id,x={id,product_id:p.id,variant_id:v?.id||null,name:p.name,size:v?.name||'',price:Number(v?.sale_price??v?.price??p.price??0),qty:1};setCart(c=>c.some(a=>a.id===id)?c.map(a=>a.id===id?{...a,qty:a.qty+1}:a):[...c,x])};return <div className="workspace standardWorkspace"><aside className="cats"><button className={category==='all'?'on':''} onClick={()=>setCategory('all')}>All</button>{categories.map(c=><button key={c.id} className={category===c.id?'on':''} onClick={()=>setCategory(c.id)}>{c.name}</button>)}</aside><section className="menu"><div className="menuhead">Menu<div className="search"><input placeholder="Search Food Item" value={q} onChange={e=>setQ(e.target.value)}/><Search/></div></div><div className="products">{products.flatMap(p=>{const vs=(p.pos_product_variants||[]);return (vs.length?vs:[null]).map(v=><button className="product" key={`${p.id}-${v?.id||'base'}`} onClick={()=>add(p,v)}><b>{p.name}</b><small>{v?.name||''}</small><div><span>{v?.name||'Regular'}</span><strong>Rs {money(v?.sale_price??v?.price??p.price??0)}</strong></div></button>)})}</div></section><Side data={data} cart={cart} setCart={setCart} refresh={refresh}/></div>}

